// src/config/solutions2Ledger.ts
//
// SOLUTIONS-2 (owner ruling, 18 Oct 2026) — the VERIFICATION LEDGER for the NCERT / Exemplar
// solutions pages of the 13 Maths chapters after the Triangles pilot. Read by
// `scripts/solutions/selectSolutions.ts`: an id marked `ref-mismatch` or `hold` is NOT published,
// and `no-verdict` publishes the row without a typed ✓/✗, whatever the rules say.
//
// ★ METHOD (every pass an independent `claude -p` agent with a fresh context; the step-3 solvers
//   never saw the stored key):
//   1. BOOK CHECK — every row that passed the deterministic rules (454) was compared with the
//      official text of the book it cites (NCERT Class X Mathematics 2026-27, jemh101–114.pdf;
//      NCERT Exemplar Class X Mathematics, jeep201–213.pdf, both from ncert.nic.in): MATCH /
//      MISMATCH (the problem is there, at another reference) / NOT_FOUND, and whether the book's
//      problem depends on a figure the row's text does not carry. Not MATCH → `ref-mismatch`;
//      MATCH but figure-dependent → `hold`.
//   2. SYLLABUS — every MATCH row against the 2026-27 IN / OUT items of
//      `syllabus2026-27.ts` for its chapter. OUT or BORDERLINE → `hold` (owner may release).
//   3. BLIND SOLVE — EVERY row that gets a ✓/✗ (all MCQs; all typed `verdict: "value"` rows) and a
//      deterministic stratified 20% sample (sha1(id) order, ceil 20% per chapter page and book) of
//      the other rows were solved with the question (and options) ONLY.
//   4. JUDGE — a further agent compared each blind answer with the stored key and steps. ANY
//      disagreement, a key judged wrong, an MCQ without exactly one correct option, or a step
//      judged wrong → `hold`. A verdict row whose question does not ask for one value → `no-verdict`.
//   5. TEXT/STEPS AUDIT — every row still published after 1-4 (343) re-read in full (question,
//      steps, answer) for wrong steps, wrong answers and drafting artifacts; anything flagged → `hold`.
//      The independent PR reviewer's 10-rows-per-chapter re-check (130 rows) feeds `hold` the same way.
// ★ The ids below are every row the rules passed at the time of verification. A candidate NOT
//   listed here is `unverified` and is never published. Rules tightened after verification (NCERT
//   "(page N)" references, relation keys like "x − y = 2", the 5-row page minimum) only REMOVE rows
//   or verdicts, so a `publish` entry below is necessary, not sufficient.
// ★ CONTENT-BOUND. Each publish / no-verdict entry carries `hash` = rowHash() (selectSolutions.ts) of
//   the question, options, keys, steps and ncertRef the verifiers saw. If the bank row changes, the hash no
//   longer matches and the row drops off the page as `unverified` until it is verified again.

// ★ SOLUTIONS-3 PR-B (owner rulings 3 and 4, 18 Oct 2026; notes prefixed "SOLUTIONS-3"):
//   - ruling 4: 96 bank rows had their `ncertRef` renumbered to the rationalised 2026-27 NCERT /
//     Exemplar PDFs (ncert.nic.in jemh1NN / jeep2NN): two fresh agents located each problem in the
//     chapter text and agreed, and a script confirmed the exercise heading, question number and
//     numbers in the PDF text. Each was then re-verified (syllabus vs the official CBSE 2026-27 Class X
//     content, blind solve of EVERY row, judge, full audit) with its new content hash. Rows the PDFs
//     could not confirm keep their old reference and stay `ref-mismatch`.
//   - ruling 3: the 36 syllabus holds were re-checked against syllabusGuard.ts and the official CBSE
//     2026-27 Class X Mathematics curriculum; a row is released only when it clearly passes both
//     (two fresh agents IN + reviewer), then blind-solved and audited like every other row.

export type LedgerStatus = "publish" | "no-verdict" | "hold" | "ref-mismatch";

export interface LedgerEntry {
  readonly status: LedgerStatus;
  /** rowHash() of the content the verifiers saw (publish / no-verdict rows). */
  readonly hash?: string;
  /** What was checked, and why a row is held. */
  readonly note: string;
}

